/**
 * Documentation generated by Claude
 * Purpose: Firestore implementation of ReviewRepository, including admin removal.
 * Role / Design Pattern: Repository Pattern implementation.
 * Outstanding Issues: Client-side checks only; Firestore security rules should enforce them too.
 */
package com.example.campsitelottery

import com.google.firebase.firestore.DocumentSnapshot
import com.google.firebase.firestore.FieldValue
import com.google.firebase.firestore.FirebaseFirestore
import java.util.Date

/**
 * Stores each review at `campsites/{campsiteId}/reviews/{userId}`, so a user has at
 * most one review per campsite. The campsite is checked in the same transaction as
 * the write, so a review can't be posted to a campsite that was just deleted or by
 * its owner.
 */
class FirestoreReviewRepository(
    private val db: FirebaseFirestore = FirebaseFirestore.getInstance(),
) : ReviewRepository {

    private fun campsite(campsiteId: String) = db.collection("campsites").document(campsiteId)

    private fun reviews(campsiteId: String) = campsite(campsiteId).collection("reviews")

    override fun getReviews(
        campsiteId: String,
        onSuccess: (List<Review>) -> Unit,
        onFailure: (Exception) -> Unit,
    ) {
        if (campsiteId.isBlank()) return onSuccess(emptyList())
        reviews(campsiteId).get()
            .addOnSuccessListener { snapshot ->
                onSuccess(ReviewPolicy.sortNewestFirst(snapshot.documents.map(::toReview)))
            }
            .addOnFailureListener(onFailure)
    }

    /**
     * Reads a stored review field by field, so a malformed review is still listed
     * for admins to remove instead of being silently dropped.
     */
    private fun toReview(doc: DocumentSnapshot) = Review(
        userId = doc.id,
        authorName = ReviewPolicy.parseStoredText(doc.get("authorName")),
        text = ReviewPolicy.parseStoredText(doc.get("text")),
        updatedAt = runCatching { doc.getDate("updatedAt") }.getOrNull(),
    )

    override fun submitReview(
        campsiteId: String,
        userId: String,
        authorName: String,
        text: String,
        onSuccess: (Review) -> Unit,
        onFailure: (Exception) -> Unit,
    ) {
        try {
            require(campsiteId.isNotBlank() && userId.isNotBlank()) { "Missing campsite or user." }
            ReviewPolicy.requireValid(text)
        } catch (e: IllegalArgumentException) {
            return onFailure(e)
        }
        val siteRef = campsite(campsiteId)
        val reviewRef = reviews(campsiteId).document(userId)
        val review = Review(userId = userId, authorName = authorName.trim(), text = ReviewPolicy.normalize(text))

        db.runTransaction { tx ->
            val site = tx.get(siteRef)
            check(site.exists()) { "This campsite no longer exists." }
            check(ReviewPolicy.canReview(site.getString("ownerId").orEmpty(), userId)) {
                "You can't review your own campsite."
            }
            tx.set(
                reviewRef,
                mapOf(
                    "userId" to review.userId,
                    "authorName" to review.authorName,
                    "text" to review.text,
                    "updatedAt" to FieldValue.serverTimestamp(),
                ),
            )
        }
            // The server sets the real timestamp; the local clock is close enough to
            // show and sort the review until the list is next loaded.
            .addOnSuccessListener { onSuccess(review.copy(updatedAt = Date())) }
            .addOnFailureListener(onFailure)
    }

    override fun removeReview(
        campsiteId: String,
        userId: String,
        expected: Review?,
        onSuccess: () -> Unit,
        onFailure: (Exception) -> Unit,
    ) {
        if (campsiteId.isBlank() || userId.isBlank()) {
            return onFailure(IllegalArgumentException("Missing campsite or user."))
        }
        val reviewRef = reviews(campsiteId).document(userId)

        // Read and delete in one transaction, so a review reposted after the admin
        // read it isn't deleted unseen. Every post sets a new updatedAt, so comparing
        // the whole review also catches a repost with the same text.
        db.runTransaction { tx ->
            val doc = tx.get(reviewRef)
            check(doc.exists()) { "This review was already removed." }
            check(expected == null || expected == toReview(doc)) { ReviewPolicy.CHANGED_MESSAGE }
            tx.delete(reviewRef)
        }
            .addOnSuccessListener { onSuccess() }
            .addOnFailureListener(onFailure)
    }
}
